#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("TOO_FEW\n");
        return 1;
    }
    if (argc > 100) {
        printf("TOO_MANY\n");
        return 1;
    }
    int prefix_len = 0;
    while (1) {
        int match = 1;
        for (int i = 1; i < argc; i++) {
            if (argv[i][prefix_len] != argv[0][prefix_len]) {
                match = 0;
                break;
            }
        }
        if (!match) break;
        prefix_len++;
        if (prefix_len >= strlen(argv[0])) break;
    }
    for (int i = 0; i < prefix_len; i++) {
        putchar(argv[0][i]);
    }
    putchar('\n');
    return 0;
}
